"""HTTP client for a REST API."""

from __future__ import annotations

from typing import Any, Mapping, Optional

import requests

DEFAULT_TIMEOUT = 10.0


class ApiError(RuntimeError):
    """Raised when an API request fails or returns an error status."""


class ApiClient:
    """Thin wrapper around :class:`requests.Session` for JSON REST APIs.

    ``base_url`` is optional when only absolute URLs are passed to :meth:`get`.
    """

    def __init__(
        self,
        base_url: str = "",
        *,
        timeout: float = DEFAULT_TIMEOUT,
        session: Optional[requests.Session] = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.session = session or requests.Session()

    def get(self, path: str, params: Optional[Mapping[str, Any]] = None) -> Any:
        """GET ``path`` and return the decoded JSON body.

        ``path`` may be an absolute URL or a path relative to ``base_url``.
        """
        url = self._resolve(path)
        try:
            response = self.session.get(url, params=params, timeout=self.timeout)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ApiError(f"GET {url} failed: {exc}") from exc
        return response.json()

    def _resolve(self, path: str) -> str:
        if path.startswith(("http://", "https://")):
            return path
        if not self.base_url:
            raise ValueError(
                f"relative path {path!r} requires a base_url"
            )
        return f"{self.base_url}/{path.lstrip('/')}"

    def close(self) -> None:
        self.session.close()

    def __enter__(self) -> "ApiClient":
        return self

    def __exit__(self, *exc_info: object) -> None:
        self.close()

import pytest
import requests

from api_fetcher import ApiClient, ApiError


class FakeResponse:
    def __init__(self, payload=None, status_code=200):
        self._payload = payload
        self.status_code = status_code

    def json(self):
        return self._payload

    def raise_for_status(self):
        if self.status_code >= 400:
            raise requests.HTTPError(f"status {self.status_code}", response=self)


class FakeSession:
    def __init__(self, response):
        self.response = response
        self.calls = []

    def get(self, url, params=None, timeout=None):
        self.calls.append({"url": url, "params": params, "timeout": timeout})
        return self.response

    def close(self):
        self.closed = True


def test_get_joins_base_url_and_path():
    session = FakeSession(FakeResponse({"ok": True}))
    client = ApiClient("https://api.example.com/", timeout=5, session=session)

    assert client.get("/v1/items", params={"q": "x"}) == {"ok": True}
    assert session.calls == [
        {
            "url": "https://api.example.com/v1/items",
            "params": {"q": "x"},
            "timeout": 5,
        }
    ]


def test_get_accepts_absolute_url_without_base():
    session = FakeSession(FakeResponse([1, 2]))
    client = ApiClient(session=session)

    assert client.get("https://other.test/data") == [1, 2]
    assert session.calls[0]["url"] == "https://other.test/data"


def test_relative_path_without_base_url_raises():
    client = ApiClient(session=FakeSession(FakeResponse()))
    with pytest.raises(ValueError):
        client.get("/v1/items")


def test_http_error_is_wrapped_in_api_error():
    session = FakeSession(FakeResponse(status_code=500))
    client = ApiClient("https://api.example.com", session=session)

    with pytest.raises(ApiError):
        client.get("/boom")

import pytest

from api_fetcher.cli import parse_params


def test_parse_params():
    assert parse_params(["q=hello", "page=2"]) == {"q": "hello", "page": "2"}


def test_parse_params_rejects_malformed():
    with pytest.raises(ValueError):
        parse_params(["missing_equals"])

